insert into public.feats (system, name, category, prerequisites, description, ability_increase, source, is_homebrew) values
('dnd35', 'Alerta', 'Geral', '', 'Você recebe +2 de bônus em todos os testes de Observar e Ouvir.', '', 'SRD 3.5', false),
('dnd35', 'Esquiva', 'Combate', 'Des 13', 'Durante sua ação, você designa um único oponente e recebe +1 de bônus de esquiva na sua Classe de Armadura contra os ataques desse oponente.', '', 'SRD 3.5', false),
('dnd35', 'Ataque Poderoso', 'Combate', 'For 13', 'Em sua ação, antes de realizar suas jogadas de ataque, você pode escolher subtrair um número de todas as jogadas de ataque corpo a corpo e adicionar a mesma quantidade a todas as jogadas de dano corpo a corpo. Esse número não pode exceder o seu bônus base de ataque.', '', 'SRD 3.5', false),
('dnd35', 'Trespassar', 'Combate', 'For 13, Ataque Poderoso', 'Se você desferir um golpe golpeando um oponente e reduzi-lo a 0 pontos de vida ou menos, você ganha imediatamente um ataque corpo a corpo adicional contra outro oponente adjacente.', '', 'SRD 3.5', false),
('dnd35', 'Trespassar Aprimorado', 'Combate', 'For 13, Ataque Poderoso, Trespassar, bônus base de ataque +4', 'Funciona como o talento Trespassar, mas não há limite para a quantidade de vezes que você pode usar essa habilidade por rodada.', '', 'SRD 3.5', false),
('dnd35', 'Iniciativa Aprimorada', 'Combate', '', 'Você recebe +4 de bônus nos testes de iniciativa.', '', 'SRD 3.5', false),
('dnd35', 'Foco em Arma', 'Combate', 'Proficiência com a arma escolhida, bônus base de ataque +1', 'Você recebe +1 de bônus em todas as jogadas de ataque com a arma selecionada.', '', 'SRD 3.5', false),
('dnd35', 'Especialização em Arma', 'Combate', 'Foco em Arma com a arma escolhida, nível de guerreiro 4º', 'Você recebe +2 de bônus em todas as jogadas de dano com a arma selecionada.', '', 'SRD 3.5', false),
('dnd35', 'Combater com Duas Armas', 'Combate', 'Des 15', 'Suas penalidades por lutar com duas armas são reduzidas. A penalidade da sua mão principal diminui para -2, e a da sua mão secundária diminui para -2 (assumindo que a arma secundária seja leve).', '', 'SRD 3.5', false),
('dnd35', 'Tiro Certeiro', 'Combate', '', 'Você recebe +1 de bônus nas jogadas de ataque e dano com armas de ataque à distância contra alvos a até 9 metros.', '', 'SRD 3.5', false),
('dnd35', 'Tiro Preciso', 'Combate', 'Tiro Certeiro', 'Você pode disparar ou arremessar armas de ataque à distância contra oponentes envolvidos em combate corpo a corpo sem sofrer a penalidade padrão de -4 na jogada de ataque.', '', 'SRD 3.5', false),
('dnd35', 'Foco em Magia', 'Geral', '', 'Adicione +1 à CD de todos os testes de resistência contra as magias da escola de magia selecionada.', '', 'SRD 3.5', false),
('dnd35', 'Penetração Mágica', 'Geral', '', 'Você recebe +2 de bônus nos testes de nível de conjurador (1d20 + nível de conjurador) para superar a resistência à magia de uma criatura.', '', 'SRD 3.5', false),
('dnd35', 'Robustez', 'Geral', '', 'Você recebe +3 pontos de vida adicionais. Você pode escolher este talento diversas vezes; seus efeitos se acumulam.', '', 'SRD 3.5', false),
('dnd35', 'Vontade de Ferro', 'Geral', '', 'Você recebe +2 de bônus em todos os testes de resistência de Vontade.', '', 'SRD 3.5', false),
('dnd35', 'Reflexos Rápidos', 'Geral', '', 'Você recebe +2 de bônus em todos os testes de resistência de Reflexos.', '', 'SRD 3.5', false),
('dnd35', 'Fortitude Maior', 'Geral', '', 'Você recebe +2 de bônus em todos os testes de resistência de Fortitude.', '', 'SRD 3.5', false),
('dnd35', 'Sucesso Decisivo Aprimorado', 'Combate', 'Proficiência com a arma escolhida, bônus base de ataque +8', 'Quando usar a arma selecionada, a margem de ameaça de acerto crítico da arma é duplicada.', '', 'SRD 3.5', false),
('dnd35', 'Derrubar Aprimorado', 'Combate', 'Int 13, Especialização em Combate', 'Você não provoca ataques de oportunidade quando tenta derrubar um oponente. Se você derrubar um oponente em combate corpo a corpo, ganha imediatamente um ataque corpo a corpo adicional contra aquele oponente como se não tivesse usado sua ação para derrubá-lo. Você também recebe +4 de bônus em seu teste de Força para derrubar.', '', 'SRD 3.5', false),
('dnd35', 'Agarrar Aprimorado', 'Combate', 'Des 13, Ataque Desarmado Aprimorado', 'Você não provoca ataques de oportunidade quando realiza uma jogada de agarrar. Além disso, você recebe +4 de bônus em todos os testes de agarrar.', '', 'SRD 3.5', false),
('dnd35', 'Mobilidade', 'Combate', 'Des 13, Esquiva', 'Você recebe +4 de bônus de esquiva na Classe de Armadura contra ataques de oportunidade provocados quando você se move para fora ou dentro de uma área sob ameaça.', '', 'SRD 3.5', false),
('dnd35', 'Ataque em Corrida', 'Combate', 'Des 13, Esquiva, Mobilidade, bônus base de ataque +4', 'Quando usar a ação de ataque com uma arma corpo a corpo, você pode se mover antes e depois do ataque, contanto que a distância total percorrida não seja maior que seu deslocamento. Você não provoca ataques de oportunidade do defensor.', '', 'SRD 3.5', false),
('dnd35', 'Maximizar Magia', 'Metamágico', '', 'Todos os efeitos numéricos variáveis de uma magia maximizada são elevados ao valor máximo. Uma magia maximizada ocupa um espaço de magia três níveis superior ao seu nível real.', '', 'SRD 3.5', false),
('dnd35', 'Acelerar Magia', 'Metamágico', '', 'Conjurar uma magia acelerada é uma ação rápida. Você pode realizar outra ação, até mesmo conjurar outra magia, na mesma rodada em que conjura uma magia acelerada. Uma magia acelerada ocupa um espaço de magia quatro níveis superior ao seu nível real.', '', 'SRD 3.5', false),
('dnd35', 'Estender Magia', 'Metamágico', '', 'Uma magia estendida dura o dobro do tempo normal. Magias com duração de concentração, instantânea ou permanente não são afetadas. Uma magia estendida ocupa um espaço de magia um nível superior ao seu nível real.', '', 'SRD 3.5', false),
('dnd35', 'Escrever Pergaminho', 'Criação de Itens', 'Nível de conjurador 1º', 'Você pode criar um pergaminho contendo qualquer magia que você conheça. A criação consome tempo e recursos (PO e XP) proporcionais ao nível da magia e do conjurador.', '', 'SRD 3.5', false),
('dnd35', 'Criar Item Maravilhoso', 'Criação de Itens', 'Nível de conjurador 3º', 'Você pode criar qualquer item maravilhoso cujos pré-requisitos você atenda. A criação consome tempo e recursos (PO e XP) proporcionais ao preço de mercado do item.', '', 'SRD 3.5', false),
('dnd35', 'Especialização em Combate', 'Combate', 'Int 13', 'Quando você usa a ação de ataque ou ataque total em combate corpo a corpo, você pode escolher sofrer uma penalidade de até -5 na sua jogada de ataque e adicionar o mesmo número como bônus de esquiva na sua Classe de Armadura. O número não pode exceder o seu bônus base de ataque.', '', 'SRD 3.5', false),
('dnd35', 'Destruir Aprimorado', 'Combate', 'For 13, Ataque Poderoso', 'Você não provoca ataques de oportunidade quando tenta atingir um objeto empunhado ou carregado por um oponente. Além disso, você recebe +4 de bônus em qualquer jogada de ataque para desferir um golpe contra um objeto.', '', 'SRD 3.5', false),
('dnd35', 'Lutar às Cegas', 'Combate', '', 'Em combate corpo a corpo, cada vez que errar devido à camuflagem, você pode rolar novamente a porcentagem de erro para ver se atinge. Invisibilidade não concede bônus de ataque contra você em combate corpo a corpo, e você mantém seu bônus de Destreza na CA.', '', 'SRD 3.5', false);
insert into public.spells (user_id, system, name, level, school, casting_time, range, components, duration, description, is_homebrew) values
(null, 'dnd35', 'Mísseis Mágicos', 1, 'Evocação', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S', 'Instantânea', 'Um dardo de energia mágica surge da ponta dos seus dedos e atinge o alvo infalivelmente, causando 1d4+1 pontos de dano de força. A cada dois níveis de conjurador acima do 1º, você cria um dardo adicional, até um máximo de cinco dardos no 9º nível. Os dardos podem ser distribuídos entre múltiplos alvos ou concentrados em um único.', false),
(null, 'dnd35', 'Bola de Fogo', 3, 'Evocação', '1 ação padrão', 'Longa (120 m + 12 m/nível)', 'V, S, M (uma bolinha de guano de morcego e enxofre)', 'Instantânea', 'Uma explosão de chamas irrompe com um rugido surdo, causando 1d6 pontos de dano de fogo por nível de conjurador (máximo de 10d6) a todas as criaturas dentro de uma área esférica de 6 metros de raio. Criaturas na área podem tentar um teste de Reflexos para reduzir o dano à metade. O fogo incendeia materiais combustíveis e derrete metais de baixo ponto de fusão.', false),
(null, 'dnd35', 'Curar Ferimentos Leves', 1, 'Conjuração', '1 ação padrão', 'Toque', 'V, S', 'Instantânea', 'Ao canalizar energia positiva através do toque, você cura 1d8 pontos de dano +1 por nível de conjurador (máximo de +5) em uma criatura viva. Como mortos-vivos são movidos por energia negativa, esta magia causa dano a eles em vez de curar, exigindo um teste de Vontade para reduzir o dano à metade.', false),
(null, 'dnd35', 'Velocidade', 3, 'Transmutação', '1 ação padrão', 'Curto (7,5 m + 1,5 m/2 níveis)', 'V, S, M (uma pitada de alcaçuz)', '1 rodada/nível', 'As criaturas afetadas movem-se e agem com rapidez extrema. Ao realizar uma ação de ataque total, os alvos podem fazer um ataque adicional com qualquer arma que estejam empunhando. Eles recebem +1 de bônus nas jogadas de ataque, +1 de bônus de esquiva na CA e nos testes de Reflexos, e um aumento de 9 metros em todos os seus deslocamentos (até o dobro do deslocamento normal).', false),
(null, 'dnd35', 'Voo', 3, 'Transmutação', '1 ação padrão', 'Toque', 'V, S, F (uma pena de asa)', '1 min./nível', 'O alvo adquire a capacidade de voar com um deslocamento de 18 metros (ou 12 metros se usar armadura média ou pesada, ou carregar carga média ou pesada) com manobrabilidade boa. Ele pode subir com metade do deslocamento e descer com o dobro do deslocamento. A magia concede estabilidade aérea total.', false),
(null, 'dnd35', 'Invisibilidade', 2, 'Ilusão', '1 ação padrão', 'Toque', 'V, S, M/DF (um cílio e um pouco de goma arábica)', '1 min./nível (D)', 'O alvo torna-se invisível, desaparecendo da visão comum. Seus pertences e equipamentos também ficam invisíveis. A magia termina imediatamente se o alvo realizar qualquer ação hostil (como atacar ou conjurar uma magia ofensiva). Criaturas invisíveis recebem +2 de bônus em jogadas de ataque contra oponentes que não possam vê-las e ignoram o bônus de Destreza de seus alvos na CA.', false),
(null, 'dnd35', 'Sono', 1, 'Encantamento', '1 rodada completa', 'Média (30 m + 3 m/nível)', 'V, S, M (uma pitada de areia fina, pétalas de rosa ou cinzas)', '1 min./nível', 'Esta magia induz um sono mágico profundo em uma ou mais criaturas vivas. Afeta um total de 4 Dados de Vida (DV) de criaturas. As criaturas com menos DVs são afetadas primeiro. Criaturas adormecidas estão indefesas. O barulho normal ou um ferimento desperta as criaturas afetadas, e gastar uma ação padrão para sacudir ou bater nelas também funciona.', false),
(null, 'dnd35', 'Detectar Magia', 0, 'Adivinhação', '1 ação padrão', '18 metros', 'V, S, M/DF', 'Concentração, até 1 min./nível (D)', 'Você detecta auras mágicas em uma área em forma de cone à sua frente. Conforme se concentra por rodadas sucessivas, você obtém mais informações: 1ª rodada: Presença ou ausência de auras mágicas; 2ª rodada: Quantidade de auras mágicas e a força da aura mais poderosa; 3ª rodada: A força e localização de cada aura, e a escola de magia correspondente de cada uma (com um teste de Identificar Magia).', false),
(null, 'dnd35', 'Curar Ferimentos Graves', 3, 'Conjuração', '1 ação padrão', 'Toque', 'V, S', 'Instantânea', 'Você canaliza energia positiva para curar 3d8 pontos de dano +1 por nível de conjurador (máximo de +15) na criatura viva tocada. Causa dano em criaturas mortas-vivas.', false),
(null, 'dnd35', 'Aumentar Pessoa', 1, 'Transmutação', '1 rodada completa', 'Curto (7,5 m + 1,5 m/2 níveis)', 'V, S, M (uma pitada de pó de ferro)', '1 min./nível (D)', 'Esta magia duplica a altura e multiplica por oito o peso de uma criatura humanoide. O alvo aumenta uma categoria de tamanho (por exemplo, de Médio para Grande), o que impõe -1 de penalidade nas jogadas de ataque e na CA, concede +2 de bônus de tamanho em Força, -2 de penalidade de tamanho em Destreza, e aumenta seu alcance natural para 3 metros (se aplicável).', false),
(null, 'dnd35', 'Escudo', 1, 'Abjuração', '1 ação padrão', 'Pessoal', 'V, S', '1 min./nível (D)', 'Um escudo invisível e móvel de força surge flutuando à sua frente. Ele concede +4 de bônus de escudo na CA. Esse bônus se aplica contra ataques incorpóreos de toque. O escudo também impede completamente que você seja atingido por Mísseis Mágicos.', false),
(null, 'dnd35', 'Armadura Arcana', 1, 'Conjuração', '1 ação padrão', 'Toque', 'V, S, F (um pedaço de couro curado)', '1 hora/nível (D)', 'Uma força mágica invisível, mas tangível, envolve o alvo, concedendo +4 de bônus de armadura na CA. Diferente de uma armadura real, a Armadura Arcana não tem penalidade de armadura, chance de falha de magia arcana ou limitação de Destreza. Por ser feita de força, o bônus se aplica contra ataques incorpóreos.', false),
(null, 'dnd35', 'Identificação', 1, 'Adivinhação', '1 hora', 'Toque', 'V, S, M (uma pena de coruja mergulhada em vinho contendo uma pérola triturada de pelo menos 100 PO)', 'Instantânea', 'Esta magia revela as propriedades mágicas de um único item sob análise. Você aprende todas as funções do item, como ativá-lo (se aplicável) e quantas cargas restam (se houver).', false),
(null, 'dnd35', 'Teia', 2, 'Conjuração', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S, M (um pedaço de teia de aranha)', '10 min./nível (D)', 'Cria um emaranhado de teias grossas e colantes que prende as criaturas na área afetada. Qualquer criatura na área deve fazer um teste de Reflexos. Se falhar, fica presa e incapaz de se mover. Para escapar ou se mover através da teia, a criatura deve realizar um teste de Força ou de Arte da Fuga (CD 20 para escapar, CD 15 para mover-se). A teia é inflamável e queima em 1 rodada se exposta ao fogo, causando 2d4 de dano de fogo às criaturas presas.', false),
(null, 'dnd35', 'Sopro de Vento', 2, 'Evocação', '1 ação padrão', '18 metros', 'V, S', '1 rodada', 'Cria uma rajada de vento forte que sobra a partir de você em uma linha de 18 metros de comprimento. Criaturas Pequenas ou menores na área podem ser derrubadas ou empurradas. Criaturas Médias devem passar num teste de Fortitude para conseguir se mover em direção ao conjurador. A rajada apaga chamas expostas (como tochas e velas) e dispersa gases e vapores.', false),
(null, 'dnd35', 'Dissipar Magia', 3, 'Abjuração', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S', 'Instantânea', 'Você pode usar Dissipar Magia para encerrar magias em andamento em um alvo (criatura ou objeto), encerrar os efeitos de magias em uma área ou contra-atacar a magia de outro conjurador. Para dissipar uma magia, você deve realizar um teste de dissipar (1d20 + seu nível de conjurador, máximo +10) contra a CD da magia (11 + nível de conjurador da magia a ser dissipada).', false),
(null, 'dnd35', 'Relâmpago', 3, 'Evocação', '1 ação padrão', '36 metros', 'V, S, M (um bastão de vidro ou âmbar e um pedaço de pele ou lã)', 'Instantânea', 'Você libera um poderoso arco elétrico que se estende a partir do seu dedo em uma linha reta de 36 metros de comprimento e 1,5 metro de largura. A eletricidade causa 1d6 pontos de dano de eletricidade por nível de conjurador (máximo de 10d6) a todas as criaturas no trajeto. Cada alvo pode fazer um teste de Reflexos para reduzir o dano à metade.', false),
(null, 'dnd35', 'Pele de Árvore', 2, 'Transmutação', '1 ação padrão', 'Toque', 'V, S, DF', '10 min./nível (D)', 'A pele do alvo torna-se dura e áspera como a casca de uma árvore, concedendo um bônus de armadura natural de +2 na CA. Esse bônus aumenta em +1 para cada três níveis de conjurador acima do 3º, até um máximo de +5 no 12º nível de conjurador.', false),
(null, 'dnd35', 'Rogar Praga', 3, 'Necromancia', '1 ação padrão', 'Toque', 'V, S', 'Permanente', 'Você toca o alvo e roga uma terrível maldição sobre ele. Você deve escolher um dos seguintes efeitos: -6 de penalidade em um valor de habilidade (mínimo 1); -4 de penalidade em jogadas de ataque, testes de resistência e testes de perícia; ou a cada rodada, o alvo tem 50% de chance de não agir. A maldição é permanente e só pode ser removida com a magia Remover Maldição ou Milagre/Desejo.', false),
(null, 'dnd35', 'Poeira da Purpurina', 2, 'Conjuração', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S, M (pó de mica moído)', '1 rodada/nível (D)', 'Uma nuvem de poeira dourada brilhante cobre todas as criaturas e objetos em uma área de 3 metros de raio. Qualquer criatura na área fica cega por toda a duração da magia si falhar em um teste de Vontade. Além disso, a poeira adere a criaturas e objetos invisíveis, delineando-os claramente e anulando os benefícios da invisibilidade.', false),
(null, 'dnd35', 'Dedo da Morte', 7, 'Necromancia', '1 ação padrão', 'Curto (7,5 m + 1,5 m/2 níveis)', 'V, S', 'Instantânea', 'Você aponta o dedo para uma criatura dentro do alcance e libera uma rajada de energia letal. O alvo deve passar em um teste de Fortitude ou morrerá imediatamente. Se passar no teste, ele sofre 3d6 pontos de dano +1 por nível de conjurador (máximo de +25).', false),
(null, 'dnd35', 'Muralha de Fogo', 4, 'Evocação', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S, M/DF (uma pitada de fósforo)', 'Concentração + 1 rodada/nível', 'Você cria uma cortina de chamas violetas e incandescentes com até 6 metros de comprimento por nível de conjurador ou um anel de chamas com raio de até 1,5 metro por dois níveis. A muralha causa 2d4 pontos de dano de fogo a criaturas a até 3 metros e 1d4 de dano a criaturas entre 3 e 6 metros. Criaturas que atravessarem a muralha sofrem 2d6 pontos de dano de fogo +1 por nível de conjurador (máximo de +20).', false),
(null, 'dnd35', 'Santuário', 1, 'Abjuração', '1 ação padrão', 'Toque', 'V, S, DF', '1 rodada/nível (D)', 'Qualquer criatura que tente atacar diretamente a criatura protegida por esta magia deve realizar um teste de Vontade. Se falhar, ela não pode atacar o alvo e perde aquela ação de ataque. O Santuário não protege o alvo contra magias de área. Se o alvo protegido realizar qualquer ação hostil, a magia é anulada imediatamente.', false),
(null, 'dnd35', 'Envenenamento', 4, 'Necromancia', '1 ação padrão', 'Toque', 'V, S', 'Instantânea; veja o texto', 'Ao tocar o alvo, você injeta um veneno mágico letal. O alvo deve fazer um teste de Fortitude imediato para não sofrer 1d10 pontos de dano temporário de Constituição. Após 1 minuto, ele deve fazer outro teste de Fortitude ou sofrerá mais 1d10 pontos de dano temporário de Constituição.', false),
(null, 'dnd35', 'Desintegrar', 6, 'Transmutação', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V, S, M/DF (uma pitada de poeira de ímã e uma pitada de cinzas)', 'Instantânea', 'Um raio verde e fino salta dos seus dedos. Faça um ataque de toque à distância. Se acertar, o alvo deve fazer um teste de Fortitude. Se falhar, sofre 2d6 pontos de dano por nível de conjurador (máximo de 40d6). Se o dano reduzir o alvo a 0 pontos de vida ou menos, ele é completamente desintegrado, restando apenas um punhado de poeira cinzenta. Se passar na salvaguarda, sofre apenas 5d6 pontos de dano.', false),
(null, 'dnd35', 'Restauração', 4, 'Conjuração', '3 rodadas', 'Toque', 'V, S, M (pó de diamante no valor de 100 PO)', 'Instantânea', 'Esta magia dissipa qualquer efeito temporário de redução de valores de habilidade ou cura todos os danos temporários a uma habilidade. Também elimina efeitos de fadiga e exaustão, e remove drenos de energia (níveis negativos), restaurando um nível drenado se conjurada em até 1 dia por nível do dreno.', false),
(null, 'dnd35', 'Compreender Idiomas', 1, 'Adivinhação', '1 ação padrão', 'Pessoal', 'V, S, M/DF (uma pitada de cinzas e grãos de sal)', '10 min./nível', 'Você compreende o significado literal de todas as palavras faladas ou escritas em qualquer idioma que ouvir ou ler. Para ler um texto escrito, você deve tocá-lo. A magia não permite que você fale ou escreva nesses idiomas, apenas compreenda.', false),
(null, 'dnd35', 'Arrombamento', 2, 'Transmutação', '1 ação padrão', 'Média (30 m + 3 m/nível)', 'V', 'Instantânea; veja o texto', 'A magia destranca ou abre portas, portões, baús ou outros recipientes trancados, sejam por fechaduras comuns, trincos, barras ou por magias como Tranca Arcana. Cada conjuração abre até dois meios de trancamento em um único objeto.', false),
(null, 'dnd35', 'Silêncio', 2, 'Ilusão', '1 ação padrão', 'Longa (120 m + 12 m/nível)', 'V, S', '1 min./nível (D)', 'Cria uma zona de silêncio absoluto em uma área esférica de 4,5 metros de raio centrada em um ponto do espaço ou em uma criatura/objeto. Nenhum som pode ser gerado ou atravessar a área. Criaturas dentro da área ficam imunes a dano sônico, mas ficam incapazes de conjurar magias com componentes verbais. Se conjurada sobre uma criatura involuntária, ela tem direito a um teste de Vontade.', false),
(null, 'dnd35', 'Curar Ferimentos Moderados', 2, 'Conjuração', '1 ação padrão', 'Toque', 'V, S', 'Instantânea', 'Você canaliza energia positiva para curar 2d8 pontos de dano +1 por nível de conjurador (máximo de +10) na criatura viva tocada. Causa dano em criaturas mortas-vivas.', false);
